window.SITE_COURSES=window.SITE_COURSES||{};SITE_COURSES["alhamasa"]={"lessons":[{"id":"alhamasa-0","title":"مقدمة باب الحماسة","summary":"","segments":[{"images":[{"src":"assets/hamasa/327-intro_page-67d10449.png","alt":"صفحة مقدمة باب الحماسة من الكتاب"}],"body":["أصل الحماسة الشدة، والحماسة الشجاعة لأن فيها تشدد القلب، يقال: حمس الأمر إذا اشتد، ويوم أحمس ورجل أحمس أي يوم شديد ورجل شجاع، ومنه قول الحارث بن وعلة: ولما رأيت الخيل ترى أثائجا علمت بأن اليوم أحمس فاجر. وسُمّيت قريش (الحُمس) لتشددها في دينها وقتالها، فقد كانت تتنسك في دينها وتتألّه في عبادتها، وكانت مانعة لهم من الغارات والسباء ومن وطء النساء من جهة المغنم، ولذلك لم يئدوا البنات ولا ولدت منهم امرأة غيرهم من جهة السباء، ولا زوّجوا أحدًا من العرب حتى يتحمّس ويدين بدينهم. وهذا الباب عقده أبو تمام لذكر مختار من أشعار العرب في الشجاعة وما يتصل بذلك كالفخر بها والحرب دونها والحضّ عليها. وربما يتعجب الناظر من إيراد بعض القطع في هذا الباب مما قد لا يظهر اتصاله به، ولكنه إذا أمعن النظر تبين له وجه ذلك، فإن لأبي تمام شفوف نظر في اختياره وربما قصد إلى معنى من وراء الظاهر، على أنه قد يُنازَع في بعض القطع."],"vocab":[["الحماسة","أصل الحماسة الشدة، والحماسة الشجاعة لأن فيها تشدّد القلب"],["حَمِسَ الأمر","اشتدّ"],["أحمس","شديد شجاع؛ يوم أحمس أي شديد"],["الحُمس","قريش، سُمّيت بذلك لتشددها في دينها وقتالها"]]},{"questions":[{"question":"ما أصل معنى الحماسة؟","options":["الكرم","الشدة","الحزن","الغزل"],"answer":1,"explanation":""},{"question":"ماذا يقال لليوم الشديد؟","options":["يوم أخضر","يوم أزرق","يوم أبيض","يوم أحمس"],"answer":3,"explanation":""},{"question":"لماذا سُمّيت قريش (الحُمس)؟","options":["لكثرة مالها","لتشددها في دينها وقتالها","لجمال خيلها","لسرعة سفرها"],"answer":1,"explanation":""},{"question":"لمن ينسب كتاب الحماسة وفق الشرح؟","options":["المتنبي","الأصمعي","الجاحظ","أبو تمام، عقد هذا الباب لمختار أشعار العرب في الشجاعة"],"answer":3,"explanation":""},{"question":"ما الذي يجمع قطع هذا الباب؟","options":["الرثاء فقط","الشجاعة وما يتصل بها كالفخر بها والحرب دونها والحض عليها","الغزل فقط","وصف الطبيعة"],"answer":1,"explanation":""}]}],"stars":{"perCorrectAnswer":1,"perfectSegmentBonus":2}},{"id":"alhamasa-1","title":"قطعة 1: قريط بن أنيف العنبري (التميمي)","summary":"","segments":[{"images":[{"src":"assets/hamasa/328-qita1_verses-f943ab2e.png","alt":"أبيات القطعة من الكتاب"}],"body":["أغار قوم من بني ذهل بن شيبان على إبل الشاعر فأخذوا له ثلاثين بعيرًا، فاستنجد قومه فلم ينجدوه، فأتى بني مازن فأنجدوه وأغاروا على إبل بني شيبان وساقوا له منها مئة بعير. فقال هذه القطعة يمدح بني مازن ويعرّض بقومه ليحرّضهم على الانتصار والانتقام وعلى الشجاعة وأخذ الثأر.","في الكتاب: اختلف الشرّاح هل أراد هجاء قومه أم تهييجهم؛ والأقرب أنه أراد تهييجهم وبعثهم على النصرة وأخذ الثأر."],"vocab":[["مازن","مازن بن مالك بن عمرو بن تميم، فالشاعر يفتخر بهم لنفسه"],["لم تستبح","لم تُستحل ولم تُنتهب؛ الاستباحة اتخاذ الشيء مباحًا"],["بنو اللقيطة","يعيّرهم بأنهم أبناء امرأة لقيطة، مبالغة في الهجاء"],["خُشُن","جمع خَشِن، يصف بني مازن بالقوة والشدة"],["الحفيظة","الغضب للحُرمة، لأن حق الحرمة الحفظ"],["ذو لوثة","اللُّوثة بالضم: الضعف، وبالفتح: القوة"],["ناجذيه","النواجذ أقصى الأضراس، ولا تبدو إلا عند اشتداد الأمر، فهي استعارة لشدة الشر"],["طاروا","أسرعوا"],["زرافات","جماعات"],["وحدانا","واحدًا واحدًا، أي فرادى"],["يندبهم","يدعوهم ويستغيثهم"],["النائبات","الشدائد، لأنها تنوب المرء أي تنزل به"],["برهانا","بيّنة"],["يجزون","يبدلون، (من) للعوض والمقابلة"],["الخشية","زيادة الخوف"]],"meaning":[["الأبيات 1-4","يقول: لو كنت من بني مازن ما استطاع ذهل بن شيبان أن ينهب إبلي، لأنهم يحملون بنصري ويغضبون إن انتُهكت حرمتهم، أشداء في اللقاء ويلينون للضعيف، شجعان إذا فرّ الجبان. إذا اشتد الشر أسرعوا جماعات وفرادى إلى إغاثة الصارخ دون أن يسألوه عما حصل أو يطلبوا منه بيّنة، فالتعلل وكثرة السؤال قبل الحرب من صفة الجبناء."],["الأبيات 5-7","أما قومي فهم كثيرو العدد لكنهم يؤثرون السلامة ولا يتعرضون للشر، يغفرون للظالم ويحسنون للمسيء ويتعللون بابتغاء الأجر، كأن الله لم يخلق لخوفه غيرهم. وليس هذا الأولى بهم، بل الأولى أن يكونوا كبني مازن حتى يُعرَفوا بالبأس والنصرة."]]},{"questions":[{"question":"ما الذي حدث للشاعر قبل قوله هذه القطعة؟","options":["أغار قوم من بني ذهل على إبله، فلم ينجده قومه وأنجده بنو مازن","فاز في معركة كبيرة","رثى أخاه","وصف رحلته في الصحراء"],"answer":0,"explanation":""},{"question":"ما معنى (لم تستبح إبلي)؟","options":["لم تُباع","لم تُسقَ","لم تُستحل ولم تُنتهب","لم تُحفظ"],"answer":2,"explanation":""},{"question":"ما (النواجذ) في قوله (أبدى ناجذيه)؟","options":["أقصى الأضراس، وهي استعارة لشدة الشر","العيون","الأيدي","السيوف"],"answer":0,"explanation":""},{"question":"ماذا تفيد (زرافات ووحدانا)؟","options":["ليلًا ونهارًا","شمالًا وجنوبًا","جماعات وفرادى","صغارًا وكبارًا"],"answer":2,"explanation":""},{"question":"لماذا سُمّيت النائبات بهذا الاسم؟","options":["لأنها تنوب المرء أي تنزل به","لأنها تأتي ليلًا","لأنها تُنسى","لأنها تنفع الناس"],"answer":0,"explanation":""},{"question":"كيف يتصرف قوم الشاعر عند الظلم؟","options":["يردون بالمثل فورًا","يهاجرون","يغفرون للظالم ويحسنون للمسيء","يستنجدون بالغرباء"],"answer":2,"explanation":""},{"question":"ما معنى (الحفيظة)؟","options":["الغضب للحرمة","الكرم","الصبر","الخوف"],"answer":0,"explanation":""},{"question":"ما معنى (برهانا)؟","options":["خوفًا","عداوة","بيّنة","وعدًا"],"answer":2,"explanation":""},{"question":"ما الأقرب من غرض الشاعر بحسب الشرح؟","options":["تهييج قومه وبعثهم على النصرة وأخذ الثأر","طلب المال","وصف الطبيعة","الاعتذار"],"answer":0,"explanation":""},{"question":"من هم (بنو اللقيطة) في البيت الأول؟","options":["أصدقاؤه","حلفاؤه","من يعيّرهم الشاعر بأنهم أبناء امرأة لقيطة، وهو هجاء مبالغ فيه","جيرانه"],"answer":2,"explanation":""}]}],"stars":{"perCorrectAnswer":1,"perfectSegmentBonus":2}},{"id":"alhamasa-2","title":"قطعة 2: شَهْل بن شيبان الزِّمّاني (كما في الكتاب)","summary":"","segments":[{"images":[{"src":"assets/hamasa/329-qita2_verses-bd1c98bf.png","alt":"أبيات القطعة من الكتاب"}],"body":["الشاعر شَهْل بن شيبان بن ربيعة بن زمّان البكري من بني بكر بن وائل، شاعر جاهلي من فرسان ربيعة المشهورين، شهد حرب البسوس، وغلب عليه اسم (الفِند) أي الجبل لأنه قال لبني بكر في إحدى الحروب: ألا ترضون أن أكون لكم فِندًا تأوون إليه؟ وقال هذه القطعة في إحدى الحروب يذكر فيها أن بعض بني قومه تجاوزوا الحد وكان قد حلم عنهم، فلما تمادوا أخذهم الليث الجائع وردّهم عن غيهم. وبيّن فيها أن الحلم ليس صالحًا في كل حين ولا نافعًا مع كل أحد، فمن الأزمنة أزمنة لا يصلح فيها إلا الشدة والحزم."],"vocab":[["صفحنا","الصفح العفو عن الإساءة"],["بنو ذهل","ذهل بن شيبان من بني بكر بن وائل"],["يرجعن","يعدن ويردّدن"],["صرّح الشر","ظهر وانكشف، كأن الشر تعرّى"],["العدوان","الاشتداد والظلم"],["دنّاهم","جازيناهم؛ والدِّين هنا الجزاء"],["كما دانوا","من باب المطابقة والمشاكلة، فالإساءة الأولى ليست مجازاة"],["مشية الليث","المِشية اسم للهيئة، أي هيئة مشي الأسد"],["غدا","ابتكر، وفي البيت السابع بمعنى سال"],["توهين","تضعيف للمضروب، من الوَهَن وهو الضعف"],["تخضيع","من الخَضَعة وهي اختلاط الصوت في الحرب، أو من الخضوع"],["إقران","طاقة، يقال أقرن فلان أي أطاق"],["كفم الزق","الزق الوعاء، وفمه فتحته؛ تشبيه لاتساع الطعنة"],["الحلم","العفو عند المقدرة وعدم تعجيل العقوبة"],["الجهل","هنا السفاهة والطيش، ضد الحلم"],["إذعان","انقياد"]],"meaning":[["البيتان 1-2","عفونا عن إساءة بني قومنا وقد تجاوزوا، وقلنا: القوم إخوة لنا. ولا بد من الصبر على القريب، وإن كثرت مضراته فيُرجى رجوعه إلى ما كان عليه من الود والائتلاف."],["الأبيات 3-7","ولكنهم تمادوا في غيهم فأظهروا الشر وصارحونا بالعداوة، ولم يبق لنا حيلة إلا القوة، فجازيناهم بما بدؤوا به. مشينا إليهم كالأسد الغاضب، نضربهم ضربًا يضعفهم وله صوت، ونطعنهم طعنًا جائفًا يسيل منه الدم بكثرة كما يسيل الشراب من الوعاء الممتلئ."],["البيتان 8-9","إذا لم ينفع الحلم ولم تنجع المداراة فإنه لا يردع السفيه إلا الشدة والغلظة. فللحلم موضعه الذي يزينه وليس هذا موضعه، كما قال النابغة الجعدي: ولا خير في حلم إذا لم تكن له بوادر تحمي صفوه أن يكدرا. فالحلم في غير موضعه ذلة، وربما كانت القوة والشر أجدر به وأنفع له من الإعراض والإحسان."]]},{"questions":[{"question":"ماذا فعل الشاعر وقومه في البداية مع بني ذهل؟","options":["هاجموهم فورًا","هربوا منهم","طلبوا المال","عفوا عنهم وصبروا على إساءتهم"],"answer":3,"explanation":""},{"question":"ما معنى (صرّح الشر)؟","options":["اختفى","ظهر وانكشف","خفّ","طال"],"answer":1,"explanation":""},{"question":"بمن شبّه الشاعر مشيهم إلى العدو؟","options":["بالذئب","بالنمر","بالصقر","بالأسد الغاضب"],"answer":3,"explanation":""},{"question":"ما (الزق) في قوله (كفم الزق)؟","options":["السيف","الوعاء","الفرس","الرمح"],"answer":1,"explanation":""},{"question":"ما المراد بـ(الجهل) في قوله (عند الجهل)؟","options":["ضد العلم تمامًا","النوم","الخوف","السفاهة والطيش"],"answer":3,"explanation":""},{"question":"ما معنى (دنّاهم كما دانوا)؟","options":["هجرناهم","جازيناهم بمثل فعلهم","سامحناهم","عاقبناهم أكثر"],"answer":1,"explanation":""},{"question":"ما معنى (الحلم) كما في الشرح؟","options":["الضعف","السرعة في الانتقام","النوم","العفو عند المقدرة وعدم تعجيل العقوبة"],"answer":3,"explanation":""},{"question":"ما الرسالة التي تبيّنها القطعة؟","options":["الحلم مذموم دائمًا","الحلم ليس صالحًا في كل حين ولا نافعًا مع كل أحد","الحرب أفضل دائمًا","لا يجوز العفو"],"answer":1,"explanation":""},{"question":"من أي قبيلة الشاعر؟","options":["من تميم","من قريش","من طيء","من بني بكر بن وائل"],"answer":3,"explanation":""},{"question":"بماذا لُقّب الشاعر ولماذا؟","options":["بالأسد لشجاعته","بالفِند أي الجبل، لأنه قال لقومه: ألا ترضون أن أكون لكم فِندًا تأوون إليه","بالبحر لكرمه","بالسيف لحدّته"],"answer":1,"explanation":""},{"question":"ما بحر القطعة؟","options":["الوافر","البسيط","الطويل","الهزج"],"answer":3,"explanation":""}]}],"stars":{"perCorrectAnswer":1,"perfectSegmentBonus":2}},{"id":"alhamasa-3","title":"قطعة 3: أبو الغول الطهوي","summary":"","segments":[{"images":[{"src":"assets/hamasa/330-qita3_verses-e2fda9b6.png","alt":"أبيات القطعة من الكتاب"}],"body":["أبو الغول الطهوي شاعر إسلامي من الدولة الأموية، لم يقف الشارح على اسمه. ذكر ابن المعتز في طبقاته أنه يكنى أبا الغول، وهو من بني طُهيّة وهم بنو عبد شمس بن أبي سُود. في هذه القطعة يمدح الفوارس الشجعان الذين أبلوا بلاء حسنًا في نصرتهم، ويذكر النزاع على ماء (الوقبى): انتزعته أحياء من بني بكر بن وائل من بشر بن حزن المازني وأخيه، فاستنصر بشر بني مازن وبني العنبر وبني يربوع من بني تميم فاستخلصوه بعد قتال شديد، ثم تنازع مازن ويربوع عليه حتى خلص الماء لبني مازن."],"vocab":[["فدت نفسي","خبر بمعنى الدعاء، أي جعل الله نفسي فداءً لهم"],["ملكت يميني","أي فديت لهم ما ملكت؛ والعرب تضيف المال إلى اليد لأنها المتصرفة فيه"],["فوارس","جمع فارس"],["صدّقوا فيهم ظنوني","ظننت بهم حسن البلاء فصدّقوا ظني ولم يخلفوه"],["يملّون","يسأمون ويضجرون، والملالة السآمة والضجر"],["المنايا","جمع مَنيّة وهي الموت"],["رحى الحرب","الرحى آلة يُطحن بها، وهي هنا استعارة لشدة الحرب"],["الزبون","الدَّفوع، من الزَّبن وهو الدفع، وسُمّيت الحرب بذلك لأنها تدفع من فيها بعضهم ببعض"],["بسيء","يقال سيء وسيّ بالتخفيف والتشديد"],["غلظ","خشونة جانب"],["تبلى","تتقادم فتفنى أو تضعف"],["بسالتهم","إقدامهم وشدتهم"],["صلوا","الاصطلاء التعرض للنار، وهنا استعارة لمقاساة شدائد الحرب"],["حمى الوقبى","الحمى كل ما يُحمى ويُمنع، والوقبى ماء لتميم على طريق البصرة"],["يؤلف","يجمع"],["أشتات","جمع شت وهو الشيء المتفرق"],["المنون","جمع منيّة وهي الموت"],["فنكّب","أبعد"],["درء","الاعوجاج والدفع"],["داووا بالجنون من الجنون","دفعوا الشر بمثله"],["الهوينى","تصغير الهُونى وهي الدعة والسكون"],["أكناف","الجوانب والنواحي"],["الهدون","الصلح والسكون، من الهدنة"]],"meaning":[["الأبيات 1-4","أفدي بنفسي وبكل ما أملك أولئك الفرسان الشجعان الذين كانوا عند حسن ظني بهم، لا يسأمون من الموت إذا اشتدت الحرب فكأنها رحى تحطم وتدفع ما فيها، بل يخوضون غمارها غير هائبين. هم قوم يعرفون مقادير الأمور ومجاري الأحوال ويعاملون بالسوء من يستحق وبالخير من هو له أهل، ولا تضعف قوتهم في حال، ولا تنقص شجاعتهم في وقت، بل حال قوتهم مستمر وضرب شجاعتهم متصل."],["الأبيات 5-7","وهم الفرسان الذين قاتلوا دون ماء الوقبى فحموه بقوتهم وبأسهم، وضاربوا دونه أقوامًا متفرقين من شتى بقاع الأرض فجمعوا منيتهم في مكان واحد، فهاب هؤلاء الفرسانَ كلُّ أحد. ودفعوا الشر بمثله. وهم لا يرضون بالدعة والسكون ولا يميلون إلى الصلح، لأنهم أشداء يعالجون الحديد ويميلون إلى الشر والخصومة والنهوض، فإن ترك الغزو يورث الذلة. ولذلك قالت العرب: (حبّ الهوينى يُكسب النَّصب)."]]},{"questions":[{"question":"ماذا يمدح أبو الغول في القطعة؟","options":["الكرماء","العلماء","الفوارس الشجعان الذين أبلوا بلاءً حسنًا","التجار"],"answer":2,"explanation":""},{"question":"ما معنى (رحى الحرب)؟","options":["آلة يُطحن بها، استعارة لشدة الحرب","نوع من السيوف","مكان القتال","الراية"],"answer":0,"explanation":""},{"question":"على أي شيء وقع النزاع بحسب الشرح؟","options":["أرض خصبة","إبل","ماء الوقبى","امرأة"],"answer":2,"explanation":""},{"question":"ما معنى (المنايا)؟","options":["جمع منيّة وهي الموت","الأماني","الضيوف","الخيل"],"answer":0,"explanation":""},{"question":"ماذا تفيد (فدت نفسي وما ملكت يميني)؟","options":["أنه يبيع ماله","أنه حزين","دعاء بأن يجعل الله نفسه وماله فداءً لهم","أنه خائف"],"answer":2,"explanation":""},{"question":"كيف يعامل الفرسان الناس؟","options":["بالسوء من يستحقه وبالخير من هو له أهل","بالسوء للجميع","باللين للجميع","لا يعاملون أحدًا"],"answer":0,"explanation":""},{"question":"ما معنى (الهوينى)؟","options":["السرعة","القوة","الدعة والسكون","الغنى"],"answer":2,"explanation":""},{"question":"من يُنسب إليهم أبو الغول؟","options":["بني طُهيّة، وهم بنو عبد شمس بن أبي سُود","بني ذهل","بني العنبر","قريش"],"answer":0,"explanation":""},{"question":"ما معنى (فنكّب عنهم درء الأعادي)؟","options":["اقترب منهم الأعداء","هزمهم الأعداء","أبعد عنهم دفع الأعداء","صالحهم الأعداء"],"answer":2,"explanation":""},{"question":"ما بحر القطعة؟","options":["الوافر","الهزج","البسيط","الكامل"],"answer":0,"explanation":""}]}],"stars":{"perCorrectAnswer":1,"perfectSegmentBonus":2}},{"id":"alhamasa-4","title":"قطعة 4: جعفر بن علبة الحارثي","summary":"","segments":[{"images":[{"src":"assets/hamasa/2-331-q04_verses-85e4c633.png","alt":"أبيات القطعة من الكتاب"}],"body":["جعفر بن علبة الحارثي من بني الحارث بن كعب، شاعر مسلم قليل الغزل، وكان فارسًا مشهورًا، وقُتل في ثأر دم سيأتي خبره في القطعة التالية. في هذين البيتين يبيّن من يستحق وصف الشجاعة حقًا."],"vocab":[["لا يكشف","الكشف هنا الخرم، وهو إسقاط أول وتد في البيت، وهو ثقيل فيتجنبه الشاعر"],["الغماء","الغمّة، وهي الكرب الذي يغشى ويسدّ طريق التفكير"],["ابن حرة","وصف يؤكد نجابة النسب وصفاء الأصل"],["غمرات","شدائد، من غمرة الماء الكثير لأنها تغمر صاحبها"],["يزورها","يأتيها ويتقحمها"],["غواشيها","قائمة السيف ومقبضه"],["صدورها","صدر السيف، أي نصله"]],"meaning":[["1-2","لا يكشف الكرب والشدة إلا الشجاع الذي يرى الموت بعينه ثم يتقدم ولا يتخلف. ثم يفخر بقومه: إذا لقوا الأعداء استعملوا سيوفهم فيهم وأشركوهم في شر الأنصباء، فمقابض السيوف في أيديهم ونصالها في أجساد الأعداء."]]},{"questions":[{"question":"ما وظيفة وصف الشاعر لمن يكشف الغمّاء؟","options":["بيان من يستحق وصف الشجاعة","ذكر ماله","وصف جمال خيله","ذكر نسب أعدائه"],"answer":0,"explanation":""},{"question":"ما معنى (غواشيها) في البيت؟","options":["نصل السيف","قائمة السيف ومقبضه","غمد السيف","ثوب الفارس"],"answer":1,"explanation":""},{"question":"ماذا يقصد بـ(صدورها)؟","options":["صدور الأعداء","صدور الخيل","صدر السيف أي نصله","صدور القوم"],"answer":2,"explanation":""},{"question":"ما معنى (غمرات)؟","options":["أموال كثيرة","أنهار","أودية","شدائد، من غمرة الماء الكثير"],"answer":3,"explanation":""},{"question":"لماذا يتجنب الشاعر الكشف (الخرم) في الوزن؟","options":["لأنه ثقيل","لأنه غير موجود","لأنه قصير","لأنه ممنوع شرعًا"],"answer":0,"explanation":""},{"question":"ما حال المقابض والنصال في آخر القطعة؟","options":["المقابض في الأعداء والنصال في أيديهم","المقابض في أيديهم والنصال في أجساد الأعداء","السيوف مكسورة","السيوف مغمدة"],"answer":1,"explanation":""},{"question":"مع أي قبيلة يُنسب جعفر بن علبة؟","options":["بنو تميم","بنو ضبة","بنو الحارث بن كعب","بنو عقيل"],"answer":2,"explanation":""}]}]},{"id":"alhamasa-5","title":"قطعة 5: جعفر بن علبة الحارثي","summary":"","segments":[{"images":[{"src":"assets/hamasa/3-332-q05_verses-62a0d367.png","alt":"أبيات القطعة من الكتاب"}],"body":["سبق أن جعفرًا أغار على بني عقيل فقتل منهم رجلًا. وكانت بين بني الحارث وبني عقيل مناوشات، ثم استعمل بنو عقيل عليه عامل مكة المخزومي، فأخذه وقيّده وحبسه عنده. وجاء العقيليون طلّاب الدم يفاوضون على الدية والفداء وأبى قومه، فما زال محبوسًا حتى قُتل. فلما قُتل قام نساء الحي يبكين عليه، ونحر أبوه نوقًا وشاءً وألقاها بين أيديهن. وفي القطعة يذكر زيارة طيف محبوبته له وهو مقيد في السجن، ويصف تجلده وقلة خوفه وشدة بأسه، فيستهين بالقيد والسجن ويتبجح بذكر الهوى والسيف حاضر."],"vocab":[["هواي","الذي أهواه، وفي ذلك إيجاز؛ وأصل الهوى الميل والمحبة"],["الركب اليمانين","ركبان الإبل خاصة، منسوبون إلى اليمن"],["مصعد","ذاهب مبعد"],["جنيب","مقود مستتبع، من الجنيبة وهي الفرس التي تُقاد خلف الركب"],["جثماني","جسمي"],["موثق","مقيّد، من الوثاق وهو القيد"],["لمسراها","السُّرى هو السير ليلًا، والمراد هنا طيفها وخيالها"],["أنّى","بمعنى من أين"],["تخلصت","الخلوص هو النفوذ"],["تزهق","تذهب وتتلاشى"],["تخشعت","الخشوع الذلة والخضوع"],["يزدهيها","يقال زهاه وازدهاه: استخفّه استخفافًا"],["وعيدكم","مثل الوعد، إلا أنه يختص بالشر والتهديد غالبًا"],["أخرق","الأخرق: الذي لا يحسن العمل"],["عرتني","أصابتني وجاءتني"],["صبابة","رقة الشوق"]],"meaning":[["1-3","يقول إن محبوبي انصرف راحلًا مع الركب اليمانين وولّوا وجوههم شطر بلادي مبعدين، فتبعهم قلبي كأنما يقودونه معهم، وجسمي هنا بمكة مأسور مقيّد. وتعجبت من سير خيال محبوبتي إليّ ليلًا وأنا على هذه الحال، وباب السجن مغلق دوني. جاء خيالها وحيّاني ثم قام مودّعًا، فلما غادر كادت نفسي تخرج جزعًا على فراقه."],["4-6","لا تظني أن حالي تغير بعدكم إلى الخضوع والذلة لأمر عارض، فلست ممن يخاف الموت، ولا تظني أن نفسي يستخفها التهديد ويخوفها الوعيد. ليس هذا القيد بشيء عندي ولا أبالي به، فهو لم يغير فيّ ما كنت عليه، وإنما الذي أصابني هو الشوق إليك ورقة الهوى، فإني أقاسي هواك في كل حال، أما وثاقي وإطلاقي فنسيان."]]},{"questions":[{"question":"أين كان جعفر وهو يقول هذه القطعة؟","options":["في ساحة الحرب","سجينًا مقيدًا بمكة","في بيته","في الصحراء"],"answer":1,"explanation":""},{"question":"من الذي زار جعفرًا في سجنه؟","options":["أبوه","عدوه","طيف محبوبته","أخوه"],"answer":2,"explanation":""},{"question":"من الذي سجنه وقيّده؟","options":["بنو تميم","بنو ضبة","أبوه","عامل مكة المخزومي"],"answer":3,"explanation":""},{"question":"ما معنى (مصعد)؟","options":["ذاهب مبعد","قادم مقبل","واقف ثابت","راكب فرسًا"],"answer":0,"explanation":""},{"question":"ما المقصود بـ(الركب اليمانين)؟","options":["ركبان الخيل","ركبان الإبل المنسوبون إلى اليمن","جنود الأعداء","أهل مكة"],"answer":1,"explanation":""},{"question":"ما معنى (موثق)؟","options":["حر طليق","نائم","مقيّد","جريح"],"answer":2,"explanation":""},{"question":"ما معنى (السُّرى)؟","options":["السير نهارًا","الجلوس","النوم","السير ليلًا"],"answer":3,"explanation":""},{"question":"ماذا يقصد الشاعر بقوله (فلا تحسبي أني تخشعت)؟","options":["أنه لم يذلّ ولم يخضع","أنه خاف الموت","أنه ندم","أنه استسلم"],"answer":0,"explanation":""},{"question":"ما الذي يصيب الشاعر حقًا بحسب القطعة؟","options":["الخوف","الشوق ورقة الهوى","الندم","الجوع"],"answer":1,"explanation":""},{"question":"ماذا فعل أبو جعفر بعد قتله؟","options":["هاجر من الديار","طلب الدية","نحر نوقًا وشاءً وألقاها بين النساء","سافر لمكة"],"answer":2,"explanation":""}]}]},{"id":"alhamasa-6","title":"قطعة 6: ربيعة بن مقروم الضبي","summary":"","segments":[{"images":[{"src":"assets/hamasa/4-333-q06_verses-47a77ecf.png","alt":"أبيات القطعة من الكتاب"}],"body":["ربيعة بن مقروم بن قيس بن جابر الضبي، من بني ضبة بن أد، فارس مخضرم، وهو من شعراء مضر المعدودين في الجاهلية والإسلام، أسلم فحسن إسلامه وطال عمره، وشهد القادسية وغيرها. في هذه الأبيات يفخر بنفسه ويذكر أنه شهد الحرب على فرس عظيم، ويذكر شيئًا من شجاعته، ثم يعرض إلى ذكر خصم يبغضه وكيف صرف هذا الخصم عنه بهجوه له."],"vocab":[["شهدت","حضرت"],["الخيل","أي راكبيها، فحذف المضاف وأقام المضاف إليه مقامه، وهذا مشهور في لسان العرب"],["طراد","حمل الفرسان بعضهم على بعض"],["أوظفة القوائم","الوظيف ما فوق الحافر من الفرس، والقائمة قدّم خيله"],["هيكل","ضخم عظيم"],["نزال","اسم فعل أمر بمعنى انزل؛ والنزول عن الخيل يكون إذا ضاق المعترك فيقاتلون على أقدامهم"],["طباق","الجمع بين معنيين متقابلين، كالجمع بين نزال ولم أنزل"],["ألد","شديد الخصومة"],["حنق","شدة الغيظ"],["مرجل","قدر"],["أرجيته","أخّرته، والإرجاء التأخير"],["قصده","القصد التوسط، وعني به الطريق المستقيم الذي لا اعوجاج فيه"],["كويته","الكيّ الإحراق الذي يترك أثرًا، وهو هنا استعارة للهجاء"],["النواظر","جبينه، فإن السمة أبلغ ما تكون في الوجه"]],"meaning":[["1-2","لقد حضرت الحرب حين مطاردة الفرسان في ساح القتال، وكنت على فرس ضخم سليم الحوافر من العيوب، فصاح الفرسان: هل من نازل؟ فكنت أول النازلين، ولم إذن أركب هذا الفرس إذا لم أنزل وأقاتل؟!"],["3-4","ورُبّ خصم شديد العداوة عليّ، كأنما تغلي العداوة في صدره غليان الماء في القدر لشدة احتراقه بالغيظ؛ أخّرته عني وصرفته إلى رشده، فأبصر أمر نفسه وتبين له مقداره، وهجوته هجاءً مُقذعًا كان كالعلامة في أعلى جبينه."]]},{"questions":[{"question":"من هو ربيعة بن مقروم؟","options":["شاعر أموي","شاعر عباسي","شاعر مخضرم من بني ضبة شهد القادسية","شاعر جاهلي مات قبل الإسلام"],"answer":2,"explanation":""},{"question":"ما موضوع هذه القطعة؟","options":["الرثاء","الغزل","وصف الطبيعة","الفخر بالشجاعة وذكر خصم صرفه بالهجاء"],"answer":3,"explanation":""},{"question":"ما معنى (طراد الخيل)؟","options":["حمل الفرسان بعضهم على بعض","سباق الإبل","هرب الخيل","رعي الخيل"],"answer":0,"explanation":""},{"question":"ماذا صاح الفرسان وقت الشدة؟","options":["اركب","نزال","اهرب","تقدّم"],"answer":1,"explanation":""},{"question":"لماذا ينزل الفرسان عن خيلهم؟","options":["عند الراحة","عند الفرار","إذا ضاق المعترك فيقاتلون على أقدامهم","عند الصلاة"],"answer":2,"explanation":""},{"question":"ما معنى (الألد)؟","options":["كثير المال","سريع الجري","كثير الكلام","شديد الخصومة"],"answer":3,"explanation":""},{"question":"بماذا شبّه الشاعر عداوة خصمه في صدره؟","options":["بغليان الماء في القدر","بنار الغابة","بهبوب الريح","بصوت الرعد"],"answer":0,"explanation":""},{"question":"ماذا يقصد بـ(كويته فوق النواظر)؟","options":["ضربه بالسيف","هجوته هجاء ترك أثرًا كالسمة على جبينه","كواه بالنار حقيقة","أكرمه"],"answer":1,"explanation":""},{"question":"ما معنى (مرجل)؟","options":["سيف","جبل","قدر","فرس"],"answer":2,"explanation":""}]}]},{"id":"alhamasa-7","title":"قطعة 7: سعد بن ناشب المازني (التميمي)","summary":"","segments":[{"images":[{"src":"assets/hamasa/5-334-q07_verses-54629cf8.png","alt":"أبيات القطعة من الكتاب"}],"body":["سعد بن ناشب بن معاذ بن جعدة المازني، من بني رزام بن مازن بن مالك بن عمرو بن تميم، شاعر إسلامي أموي، كان من فتاك بني تميم بالبصرة ومن مردة العرب. وخبر القصيدة أنه أصاب دمًا ثم هرب، فطلبه أمير البصرة بلال بن أبي بردة فلم يجده، فأمر بهدم داره. فقال سعد هذه الأبيات يفخر بنفسه، ويذكر أن داره لا تعني له شيئًا إزاء إدراك مطلبه بسيفه، وأنه إن عُيّر بالهرب فسيزيل هذا العار بسيفه."],"vocab":[["سأغسل عني العار","الغسل استعارة لإزالة العار"],["قضاء الله","يصح فيه الرفع والنصب؛ فعلى الرفع هو فاعل ومعناه حكم الله، وعلى النصب مفعول معناه الموت، والمعنى: يجلب الموت عليّ ما يجلبه"],["أذهل","الذهول ترك الشيء تناسيًا وتلاهيًا"],["العِرض","ما يُمدح في نفس الإنسان أو يُذم، وقيل الحسب وهو فعال المرء وفعال آبائه؛ والمقصود به سمعة الإنسان وصيته بين الناس"],["المذمة","الذم والسُّبّة"],["حاجبا","الحاجب هو المانع والساتر"],["تلادي","التلاد المال القديم، وهو ما وُلد عندك، وضده الطارف؛ وخُص التلاد لأن النفس به أضنّ"],["تراث","المال المخلّف عن الميت، سُمّي بذلك اعتبارًا بمآله"],["العواقب","مآلات الأمور"],["عزمات","جمع عزمة، من العزم وهو توطين النفس وعقد القلب على أمر يفعله"],["مقطع الأمر","فصله والخروج منه"],["تردع","الردع الكف، والرَّدع هنا الهيبة والتعظيم"],["هائب","الهيبة: الإجلال أو الخوف والذعر"],["رزام","بنو رزام، قوم الشاعر من بني مازن"],["رشحوا","هيّئوا وأعدّوا وربّوا، والترشيح التهيئة والإعداد"],["مقدّمًا","متقدمًا عن قومه، بكسر الدال"],["خوّاضًا","صيغة مبالغة من خائض"],["الكتائب","جمع كتيبة، وهي القطعة من الجيش مجتمعة"],["نكّب","أبعد"],["يستشر","الاستشارة طلب الرأي وإبداؤه مشاورة"]],"meaning":[["1-4","لئن عُيّرت بالهرب فسأجعل سيفي مزيلًا لهذا العار عني بما أظهره من الانتقام والانتصار، ولا أبالي بما يجرّه عليّ القضاء من المكروه. أما داري التي أحرقتم فإني سأسلو عنها، وسأجعل هدمها وقاية لنفسي مما يلحقني من مذمة. وإذا طلبت معالي الأمور هان عليّ ترك المال في سبيلها، وما الدار التي هدمتم غدرًا إلا مال رجل يتنزه عن المطالبة به."],["5-6","أنا رجل شجاع القلب مقدام، لست بحاجة إلى رفيق وصاحب، ولست بمستنصر أخًا أو صديقًا، بل أقدم على الأمور وحيدًا، فإني إذا هممت بالشيء بادرت فعله ولم أتروَّ فيه، وأنفذت عزيمتي غير هائب له."],["7-9","فيا قومي من بني رزام، هيّئوا بي رجلًا يتقدم إلى الموت بشجاعة ويقتحم الشدائد والحروب بجسارة، لا يجبن ولا يفر، فإني ذلك الرجل. وإني إذا هممت بالأمر أتبعت الهمة الفعل من غير تردد، معتزٌّ بنفسي مستبدٌّ برأيي، لا أعتبر الناس ولا أرى غيري مستشارًا، ولا غير سيفي صاحبًا ومعينًا."]]},{"questions":[{"question":"ما سبب هدم دار سعد؟","options":["أنه أحرقها بنفسه","أنه باعها","أنه تركها للفقراء","هرب بعد أن أصاب دمًا وطلبه أمير البصرة فلم يجده"],"answer":3,"explanation":""},{"question":"من أمر بهدم داره؟","options":["بلال بن أبي بردة أمير البصرة","الحجاج","زياد","أبوه"],"answer":0,"explanation":""},{"question":"بماذا يعد الشاعر إزالة العار الذي لحقه؟","options":["بالمال","بالسيف","بالاعتذار","بالشعر"],"answer":1,"explanation":""},{"question":"ماذا يقصد بـ(سأغسل عني العار)؟","options":["غسل ثيابه","الاستحمام","استعارة لإزالة العار","النوم"],"answer":2,"explanation":""},{"question":"ما معنى (التلاد)؟","options":["المال الجديد","الخيل","الإبل فقط","المال القديم الذي وُلد عندك"],"answer":3,"explanation":""},{"question":"ما ضد التلاد؟","options":["الطارف","التراث","العِرض","الحاجب"],"answer":0,"explanation":""},{"question":"ما معنى (العِرض) في القطعة؟","options":["ماله","سمعة الإنسان وصيته بين الناس","داره","قوته"],"answer":1,"explanation":""},{"question":"ما معنى (الكتائب)؟","options":["الخيل فقط","الأسلحة","قطع الجيش مجتمعة","الأسرى"],"answer":2,"explanation":""},{"question":"ماذا يقصد بقوله (ولم يرضَ إلا قائم السيف صاحبا)؟","options":["أنه يحب القتال مع الجيش","أنه يستشير قومه","أنه يترك السيف","لا يريد غير سيفه صاحبًا ومعينًا"],"answer":3,"explanation":""},{"question":"ما موقفه من الاستشارة؟","options":["لا يستشير غير نفسه","يستشير الحكماء","يستشير قومه","يستشير الأمير"],"answer":0,"explanation":""}]}]},{"id":"alhamasa-8","title":"قطعة 8: ثابت بن جابر الفهمي (تأبّط شرًّا)، ويقال إنها له","summary":"","segments":[{"images":[{"src":"assets/hamasa/6-335-q08_verses-d1f4acbc.png","alt":"أبيات القطعة من الكتاب"}],"body":["ثابت بن جابر بن سفيان الفهمي، من بني فهم بن عمرو بن قيس عيلان، شاعر جاهلي وأشهر صعاليك العرب وفتاكهم، وأحد العدّائين المشهورين. قيل سُمّي (تأبّط شرًّا) لأنه قتل غولًا فوضعها تحت إبطه وقدم على قومه فقالوا: تأبط شرًّا، وقيل بل رأته أمه خارجًا متأبطًا سيفه فقالت: قد تأبط شرًّا، وقيل غير ذلك. وقال هذه القصيدة يثني فيها على رجل أجزل عطيته فأجزل أعطاه، فمدحُه له قائم مقام شكره. وهي قصيدة رائعة وصف الممدوح فيها بالكرم والشجاعة وشدة البأس وقوة الجانب وصدق أبي عثمان."],"vocab":[["مُهدٍ","اسم فاعل من الإهداء، يقال أهداه هدية فهو مهدٍ"],["ابن عم الصِّدق","قيل هو ابن عمه حقيقة، وقيل أراد المبالغة في تمكن الموصوف من الصفة، كما يقال أخو المجد وابن الكرم"],["شَمس بن مالك","إن لم يكن ابن عمه حقيقة فهو من بني مالك بن فهم بن غنم من الأزد، وقيل اسمه شُمس بضم الشين"],["ندوة الحي","أصل الندوة الجمع، والنديّ والنادي: المجلس ومكان اجتماع القوم"],["عطفه","جانبه"],["الهجان","الإبل البيض"],["الأوارك","جمع آركة، وهي التي رعت نبت الأراك"],["قليل التشكّي","عديم الشكوى، والعرب قد تطلق القلة وتريد العدم"],["كثير الهوى","كثير الهوى لمعالي الأمور ومكارمها"],["شتى","مفترق"],["النوى","الوجهة والقصد"],["المسالك","الطرق، من سلك الطريق"],["بموماة","بصحراء"],["جحيشًا","منفردًا"],["يعروري ظهور المهالك","اعروري الفرس: ركبه عاريًا، وهو هنا استعارة لركوب المهالك على صعوبتها وشدتها"],["وفد الريح","أول ما يهب منها، وذلك أشدها وأسرعها"],["كرى النوم","النوم الخفيف"],["كالئ","حافظ، والكلاءة الحفظ"],["شيحان","حذر حازم"],["فاتك","الجريء الذي لا يبالي بما هجم عليه والذي يفاجئ غيره بالمكروه"],["ربيئة","عين القوم الذي يرصد لهم من موضع عالٍ"],["سلّة","استلال السيف مرة"],["أخلق باتك","سيف أملس قاطع"],["قِرن","النظير"],["تهلّلت","استبشرت وضحكت"],["نواجذ أفواه المنايا الضواحك","النواجذ أقصى الأضراس، وهو مجاز رائق لموت القرن كأن المنايا تضحك فرحًا بقدومه"],["الوحشة","التفرد والبعد عن الناس"],["الأنس الأنيس","المكان الذي يرتاح فيه ويأنس به ويأوي إليه، وقوله الأنس الأنيس تأكيد وإمعان في الوصف"],["أم النجوم","الشمس، وقيل لها ذلك لأنها أعظم النجوم، ومعظم الشيء أمه كالفاتحة أم الكتاب"],["الشوابك","المشتبكة"]],"meaning":[["1-2","يقول: إني سأهدي ثنائي ومدحي وأقصد به ابن عمي الفاضل الكريم شمس بن مالك، ولأمدحنه حتى يهتز طربًا من علو المدح كما اهتززت فرحًا من عطائه لي في سابق الأيام، فقد أعطاني كرام الإبل ونجائبها، وهل جزاء الإحسان إلا الإحسان؟"],["3-5","أما شمس فرجل صبور على النوائب والعلّات، لا يظهر تشكيًا ولا ضعفًا إن أهمّه أمر، وهو عالي الهمة بعيد المطامح، يقصد معالي الأمور بكل وجه على تفرق سبلها، فيصبح في صحراء ويمسي في أخرى، ولا يبالي بالمهالك في سبيل تحقيق عزمه وبلوغ غايته، وهو جَلْد شديد حتى إنه ليسبق الريح الشديدة من سرعة عدوه وسعة خطوه."],["6-9","وهو لشدة تيقظه لا ينام إلا النومة الخفيفة، وليس بغافل إن نام، بل لا يزال له من قلبه حافظ، فهو حازم حذر، وهو في حال يقظته عيناه طليعة لقلبه، فما يرى أمرًا ينكره حتى يسارع إلى سلّ سيفه القاطع. فإذا انبرى إليه رجل يساويه شجاعة وقوة لم تغن ذاك شجاعته ولا قوته، وما يلبث أن يخر صريعًا بضربة من سيفه فتضحك له المنايا. وهو رجل لا يأنس إلا بنفسه، بل تمام أنسه في تفرده عن الناس واعتزاله الخلق، وهو بصير بالطرق مستغنٍ عن دليل، بل يهتدي بالنجوم كما تهتدي الشمس في طريقها."]]},{"questions":[{"question":"من هو قائل القطعة بحسب الشرح؟","options":["ثابت بن جابر الفهمي (تأبّط شرًّا)","عنترة","الحطيئة","امرؤ القيس"],"answer":0,"explanation":""},{"question":"ما أشهر صفات ثابت بن جابر؟","options":["تاجر مشهور","من أشهر صعاليك العرب وفتاكهم وعدّائيهم","قاضٍ","خطيب"],"answer":1,"explanation":""},{"question":"لماذا قال ثابت هذه القطعة؟","options":["ليهجو قومه","ليرثي أخاه","ليثني على رجل أجزل عطيته","ليصف رحلة"],"answer":2,"explanation":""},{"question":"ما المراد بـ(ابن عم الصدق) في القطعة؟","options":["أنه كاذب","أنه غريب","أنه عدو","المبالغة في تمكن الصفة منه"],"answer":3,"explanation":""},{"question":"من هو الممدوح؟","options":["شمس بن مالك","أبو عثمان","الأحيمر","قرن الشاعر"],"answer":0,"explanation":""},{"question":"ما معنى (الهجان)؟","options":["الخيل","الإبل البيضاء","الغنم","الجمال السود"],"answer":1,"explanation":""},{"question":"ما معنى (النوى) في البيت الثالث؟","options":["النوم","الطعام","الوجهة والقصد","الطريق الوعر فقط"],"answer":2,"explanation":""},{"question":"ماذا يقصد بـ(يعروري ظهور المهالك)؟","options":["يهرب منها","يرثي أهلها","يبني المنازل","يركب المهالك على صعوبتها"],"answer":3,"explanation":""},{"question":"بماذا شبّه الشاعر سرعة الممدوح؟","options":["يسبق وفد الريح","يسبق البرق","يسبق الخيل","يسبق الطير"],"answer":0,"explanation":""},{"question":"ما معنى (كرى النوم)؟","options":["النوم الطويل","النوم الخفيف","السهر","الكسل"],"answer":1,"explanation":""},{"question":"من هو (الربيئة)؟","options":["الجندي النائم","الدليل","عين القوم الذي يرصد لهم من مكان عالٍ","الفارس"],"answer":2,"explanation":""},{"question":"بماذا يهتدي الممدوح في الصحراء؟","options":["بالدليل","بالخريت","بالقافلة","بالنجوم"],"answer":3,"explanation":""}]}]},{"id":"alhamasa-9","title":"قطعة 9: بعض بني قيس بن ثعلبة","summary":"","segments":[{"images":[{"src":"assets/hamasa/7-336-q09_verses-5202997c.png","alt":"أبيات القطعة من الكتاب"}],"body":["نسبها أبو تمام لبعض بني قيس بن ثعلبة من بني بكر بن وائل من ربيعة، وسمّاه بعضهم فقال هو المرقّش الأكبر عمرو بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة، والقصيدة بهذه الرواية لا تصح نسبتها له، لأن الشاعر يقول فيها (إنا بني نهشل) ونهشل هو ابن دارم من بني زيد مناة بن تميم من مضر، فأين الرَّبَعي من المُضري! ونُسبت القصيدة لبشامة بن حزن النهشلي وقيل غيره من بني نهشل. وفي هذه القصيدة يفخر الشاعر بكرم قومه وطيب الأصل وطيب المحتد، واستباقهم المكرمات، وشجاعتهم وبأسهم."],"vocab":[["محيّيك","من يلقي عليك التحية؛ وقوله (فحيّينا) ظاهره استعطاف المرأة، لكنه أراد الإشارة إلى كرم أصلهم وطيب عرقهم"],["جُلّى","مؤنث أجلّ، وهي الحادثة العظيمة والأمر الجليل"],["سراة","جمع سَرِيّ، وهو الشريف من الناس والسيد في القوم"],["بنو نهشل","بنو نهشل من بني دارم من بني زيد مناة بن تميم"],["لا ندّعي لأب عنه","لا ننتسب لأب غير أبينا"],["يشرينا","يستبدل بنا غيرنا، أي لا هو يستبدل بنا"],["تُبتَدر","الابتدار الاستباق"],["غاية","غاية السبق، وهي خشبة تُنصب فيستبقون إليها"],["السوابق","جمع سابق، وهو أول القوم وأسبقهم"],["المصلّين","جمع المصلّي، وهو ثاني القوم في السبق"],["افتلينا","الفلو والافتلاء: التربية والتهيئة"],["نُرخص","الرُّخص في السعر، وهو قلته وسهولته"],["الروع","الخوف، والرُّوع محل الخوف وهو القلب؛ والمراد بالروع هنا الحرب"],["نُسام","من السَّوم وهو المفاوضة في السعر"],["أغلينا","ضد أرخصنا، وفي ذلك طباق"],["مفارقنا","جمع مفرق، وهو موضع انفراق الشعر من الرأس؛ وابيضاضها لكثرة ما نقاسي من الشدائد والحروب"],["المرجل","القدر، وهو هنا استعارة لاصطلاء نيران الحرب، ويجوز أنه إشارة إلى كرمهم وكثرة ضيفانهم فنار قدورهم لا تنطفئ"],["نأسو","الأسو مداواة الجراح، وهو استعارة لدفع الديات بدفع المال"],["الكماة","جمع كامٍ، وهو الشجعان، كغُزاة وغازٍ"],["المحاموا","الذابون والدافعون"],["حد الظُّبات","شفرة السيف وحدّه، والظُّبة ما يلي ذباب السيف من حدّه"],["جلّت","عظُمت"],["نركب الكُره","نقدم على المهالك والأمر المكروه"],["الحفاظ","الحماية والرعاية"],["تواتينا","توافقنا وتطاوعنا"]],"meaning":[["1-2","إنا مسلّمون عليك أيتها المرأة وملقون عليك التحية، فقابلينا بمثلها فإنا أهل لأن تُلقى لنا التحايا. وإن كنتِ تسقين كرام الناس فنحن أولى الناس بالسقي، فاسقينا وأجرينا مجراهم، وإن ذكرتِ في يوم أمرًا جليلًا وأشدتِ فيه بذكر خيار الناس فاذكرينا، فنحن من خيارهم وكرامهم."],["3-5","نحن، أعني بني نهشل، لا ننتسب لأب غير أبينا، فإلى أبينا منتهى الكرم، ولا هو يبغي بنا بدلًا، لأنا بنون كرام سادة لمسوَّد. فمآثرنا وأفعالنا حميدة، ونسبنا وحسبنا شريف. فإذا كانت مكرمة فإنا نستبقها قبل الناس فنكون أول من يبادر إليها، ولا يصل إليها قبلنا أحد، فكلنا سابقون كرام أشراف. وإذا هلك السيد منا خلفه أيُّ غلام فينا، فلا نفتقر لسيد ما حيينا إذ كلنا سادة أنجاب."],["6-9","وإذا قامت الحرب وجدتنا نقدم إليها ببسالة، فتهون علينا في المعالي نفوسنا، فإن كان وقت السِّلم رأيتها نفوسًا عزيزة لا تهان لأحد. وقد جرّبنا الحروب وصلينا بحرِّها وقاسينا الشدائد حتى ابيضت رؤوسنا وعلاها الشيب. ونيران حربنا مستعرة دائمًا لا تُخمد. فإذا التقينا بهم فقتلنا منهم فإنا نَدِي قتلاهم بالمال وليس لهم منا إلا الدية، أما أن يقتصّوا فيقتلوا منا فذلك محال، فإنا لا نُقتل إلا في الحرب. ونحن نتقدم في الغزوات لا نهاب اللقاء، وما أفنانا إلا صيحاتُ أبطالنا: هل من مبارز؟ هل من مدافع؟ فكلنا فرسان. بل لو وزّعتنا على القبائل فجعلت منا واحدًا في كل ألف ثم دعوتَ: من فارسكم؟ لظن كل واحد منا أنه هو المعنيُّ دون الألف."],["10-12","وإذا تباعد الشجعان عن سيوفنا خوفًا وقصُرت سيوفنا شيئًا فإنا نجعل وصلَها خُطانا إلى أعدائنا ومدَّ أيدينا إليهم. ولأننا قوم تعودنا الحرب فإنك لا تجد في نسائنا نائحة ولا باكية ولو مات مَن مات! فقد ألِفنا المصائب والقتل، نُقدِم على المهالك والمكاره غير آبهين، فيزيلها عنا صبرنا على الشدائد ومحافظتنا على الكرم واستعمالنا سيوفنا المطاوعة لنا."]]},{"questions":[{"question":"من نسب أبو تمام القصيدة؟","options":["لبني تميم","لبعض بني قيس بن ثعلبة","لعنترة","لبني أسد"],"answer":1,"explanation":""},{"question":"لماذا لا تصح نسبتها للمرقّش بحسب الشرح؟","options":["لأنه لم يقل الشعر","لأنه كان غير عربي","لأن الشاعر يقول (إنا بني نهشل) ونهشل من تميم المضرية والمرقش ربعي","لأنها مرثية"],"answer":2,"explanation":""},{"question":"ما موضوع القصيدة؟","options":["الغزل","الرثاء","الهجاء","الفخر بالكرم وطيب الأصل والشجاعة"],"answer":3,"explanation":""},{"question":"ما معنى (جُلّى)؟","options":["الأمر العظيم الجليل","الأمر الهين","الصحراء","الطريق"],"answer":0,"explanation":""},{"question":"من هم (السراة)؟","options":["العبيد","الأشراف والسادة من القوم","الأعداء","الغرباء"],"answer":1,"explanation":""},{"question":"ما معنى (غاية) في (إن تُبتدر غايةٌ يومًا لمكرمة)؟","options":["نهاية الحرب","نهاية الطريق","غاية السبق وهي خشبة تُنصب فيستبقون إليها","علم"],"answer":2,"explanation":""},{"question":"ما معنى (الروع) في قوله (رخصنا يوم الروع أنفسنا)؟","options":["السعادة","الشبع","الراحة","الخوف، والمراد به الحرب"],"answer":3,"explanation":""},{"question":"ما البلاغة في (أرخصنا وأغلينا)؟","options":["طباق","جناس","سجع","تشبيه"],"answer":0,"explanation":""},{"question":"لماذا ابيضت مفارقهم؟","options":["لكبر السن فقط","لكثرة ما قاسوه من الشدائد والحروب","للمرض","لشدة الحر"],"answer":1,"explanation":""},{"question":"بماذا يدون قتلاهم من الأعداء؟","options":["بالسيف","بالثأر","بالمال (الدية)","بالأسر"],"answer":2,"explanation":""},{"question":"ماذا يقصد بـ(نأسو)؟","options":["نحزن","ننام","نغزو","نداوي الجراح، وهو استعارة لدفع الدية"],"answer":3,"explanation":""},{"question":"لماذا لا تجد في نسائهم نائحة ولا باكية؟","options":["لأنهم ألفوا المصائب والقتل وتعودوا الحرب","لأنهم لا يموتون","لأنهم يمنعون البكاء بالقوة","لأنهن لا يحببن أزواجهن"],"answer":0,"explanation":""}]}]},{"id":"alhamasa-10","title":"قطعة 10: الشَّمَيْذر الحارثي","summary":"","segments":[{"images":[{"src":"assets/hamasa/8-337-q10_verses-985a4153.png","alt":"أبيات القطعة من الكتاب"}],"body":["هذه القطعة مشهورة للشميذر الحارثي، ونسبها بعضهم لسويد بن صميع المرثدي، وكلاهما شاعر فارس جاهلي من بني الحارث بن كعب بن عمرو بن علة بن جلد بن مالك (مذحج). وقيل إن خبر القطعة أن رجلًا من بني العمومة قتل أخا الشاعر غيلة، فأخذ الشاعر الدية ثم قتل القاتل جهارًا في السوق، فيذكر في هذه القطعة انتصاره واحتكامه للسيف لا لغيره، ويعرّض في البداية ببني عمه فيحطّ من قدرهم ويذكّرهم بوقعة (الغمير) التي كانت عليهم."],"vocab":[["صحراء الغمير","موضع قريب من ذات عرق"],["القوافيا","جمع قافية، وأراد القصائد؛ والعرب تسمي القصيدة قافية، ثم اصطلح أهل العروض على تسمية آخر البيت بذلك، لأنه يقفو الكلام أي يتبعه"],["سلّة","أراد بها السرقة"],["ضَيمًا","الظلم والإذلال"],["نحكّم قاضيًا","نرتفع إلى شخص نفوض له الحكم بيننا في أمرنا"],["حكم السيف","قضاؤه وفصله"],["مسلَّط","ممكَّن فيكم ومحكَّم عليكم"],["جرّت الحرب","جنت الحرب"],["مدانيًا","يسيرًا يُحتمل الصبر عليه"],["لم نكن ظلمنا","يريد أنه لم يبدأ بالظلم، والعرب تقول للبادئ أظلم"],["التقاضي","استيفاء الحقوق، والقضاء الحكم فيها"]],"meaning":[["1-3","يا بني عمنا! دعوا التفاخر بالأشعار والتمدّح بالمآثر، فإنكم بهزيمتكم في صحراء الغمير قد دفنتم كل صالحة لكم، فما عاد لكم شيء تفخرون به بعد تلك العيبة. واعلموا أننا لسنا مِثلَ من كنتم تعتدون عليهم، فتقتلون منهم غيلة وتسرقون منهم خلسة، ثم لا يجدون سبيلًا إلا السكوت وقبول الظلم أو الشكوى ونصب الحكّام للقضاء. فلسنا من أولئك في شيء، بل نحكّم فيكم السيف ونأخذ حقنا بالعنوة والقهر ولا نرضى حتى يرضى السيف من دمائكم."],["4-5","ولقد ساءني ما جنته هذه الحرب من سفك دمائكم لأنكم بنو عمنا، ويعز علينا ذلك، ولو كان مكروهكم قليلًا لاحتملناه وأغضينا على القذى، ولكن زاد الأمر وبلغ السيل الزُّبى. ولا تقولوا إنا ظلمناكم في هذه الحرب، فإن البادي أظلم، ولكننا تجاوزنا في استيفاء حقنا وجازيناكم بالضِّعف، وكذلك نحن نكيل بالصاع صاعين."]]},{"questions":[{"question":"لمن تُنسب هذه القطعة في المشهور؟","options":["لعنترة","للحطيئة","للشميذر الحارثي","لزهير"],"answer":2,"explanation":""},{"question":"إلى أي قبيلة ينتمي الشميذر وسويد بن صميع؟","options":["بنو تميم","بنو بكر","بنو أسد","بنو الحارث بن كعب من مذحج"],"answer":3,"explanation":""},{"question":"ما معنى (القوافي) في البيت الأول؟","options":["القصائد","الخيل","الإبل","السيوف"],"answer":0,"explanation":""},{"question":"ماذا يذكّر الشاعر بني عمه؟","options":["بنسبهم","بوقعة الغمير التي كانت عليهم","بكرمهم","بسفرهم"],"answer":1,"explanation":""},{"question":"ما معنى (سلّة) في قوله (تصيبون سلّة)؟","options":["الحرب","الحيلة","السرقة","الصداقة"],"answer":2,"explanation":""},{"question":"ما معنى (الضيم)؟","options":["الكرم","الشجاعة","الرحمة","الظلم والإذلال"],"answer":3,"explanation":""},{"question":"بماذا يحكم الشاعر في خصومه؟","options":["بالسيف","بالقاضي","بالمال","بالصلح"],"answer":0,"explanation":""},{"question":"ماذا يقصد بقوله (فنرضى إذا ما أصبح السيف راضيا)؟","options":["أنه يطلب الصلح","لا يرضى حتى يرضى السيف من دمائهم","أنه يرضى بالمال","أنه يندم"],"answer":1,"explanation":""},{"question":"لماذا يقول الشاعر إنه ساءه ما جرت الحرب؟","options":["لأنه خسر الحرب","لأنه خاف","لأنهم بنو عمه ويعز عليه سفك دمائهم","لأنه فقير"],"answer":2,"explanation":""},{"question":"ماذا يقصد بـ(نكيل بالصاع صاعين)؟","options":["نبيع الحنطة","نرد المثل","نتصدق","نجازي بالضعف"],"answer":3,"explanation":""}]}]},{"id":"alhamasa-11","title":"قطعة 11: قطري بن الفجاءة المازني","summary":"","segments":[{"images":[{"src":"assets/hamasa/9-338-q11_verses-04841256.png","alt":"أبيات القطعة من الكتاب"}],"body":["هو جعوْنة بن مازن بن يزيد بن زياد التميمي المازني، من بني مازن بن مالك بن عمرو بن تميم، شاعر إسلامي، وسمي (قطريًّا) نسبة إلى موضع اسمه قطر بين البحرين وعُمان، لأنه غاب إلى اليمن ثم أتى قومه فجاءة، وسمي أبوه (الفجاءة). وقطري أحد زعماء الخوارج المشهورين، وكان خطيبًا مفوهًا وفارسًا شجاعًا، وهو من الأزارقة، أتباع نافع بن الأزرق بن قيس الوائلي البكري، من أشد فرق الخوارج بأسًا وأقواها شكيمة، وقُتل قطري خارجًا في ولاية الحجاج فتفرقت الأزارقة بعده. وهذه قطعة حماسية جميلة يحث فيها على الشجاعة والإقدام وثبات القلب ورباطة الجأش، ويضرب بنفسه في ذلك المثل."],"vocab":[["يركنن","أصلها يركن، زيدت عليها نون التوكيد المخففة، والمعنى: لا يميلن؛ والركون إلى الشيء الميل إليه"],["الإحجام","النكوص والانهزام"],["يوم الوغى","يوم الحرب"],["الحِمام","الموت"],["دريئة","الحلقة التي يُتعلَّم عليها الطعن، وتقدم أن الدرء الدفع ومنه سميت الدريئة بذلك"],["من عن يميني","أي من جانب يميني، و(عن) هنا اسم على المشهور"],["خضبت","الخضب والخضاب: التلوين والصبغ، يقال بنان مخضّب أي مصبوغ بالحناء"],["تحدّر","سال"],["أكناف","جمع كنف، وهو جوانب الشيء ونواحيه"],["سَرجي","ما يوضع على الفرس ليُركب عليه"],["عنان لجامي","سير اللجام، وهو الذي تُمسك به الدابة"],["جذع البصيرة","الجذع من الخيل ما تم له سنتان، وهو في البصيرة مجاز"],["قارح الإقدام","القارح من الخيل ما تم له خمس سنين، وهو في الإقدام مجاز؛ وهذا طباق، وكثيرًا ما تقابل العرب بين القارح والجذع"]],"meaning":[["1-4","لا يميلنّ أحد منكم إلى النكوص والتراجع إذا استعرت نار الحرب فيجبن خوفًا وجزعًا من الموت، فليس من الموت محالة، واعتبروا بحالي، فلقد رأيتني حين اشتدت بي الحرب يومًا، فكنتُ كأني غرَض تتعاوره الرماح من كل جانب، فانتصبتُ لها شجاعة، وما ازددتُ إلا ثباتًا، وسال الدمُ من الجروح في كل جسمي حتى خضب الدمُ اللجامَ بما سال من الجروح في أعلى جسدي، وخضَب السَّرجَ بما سال من الجروح في أسفل جسدي. ومع هذا كله فإني قد انصرفتُ من اللقاء وقد سلمتُ ونلتُ من أعدائي ولم ينالوا مني، وما ردَّني هذا الذي ذكرتُ لك عن خوض الحروب، بل ما زلتُ على رأيي الأول وبصيرتي الجذعة في الإقدام عليها، وازددتُ خبرةً في الحرب وصار إقدامي قارحًا."]]},{"questions":[{"question":"ما اسم قطري الحقيقي؟","options":["ثابت بن جابر","سعد بن ناشب","ربيعة بن مقروم","جعونة بن مازن"],"answer":3,"explanation":""},{"question":"لماذا سُمّي (قطريًّا)؟","options":["نسبة إلى موضع اسمه قطر بين البحرين وعُمان","لأنه من قطر","لأنه ولد في اليمن","لأنه قتل قاطرًا"],"answer":0,"explanation":""},{"question":"إلى أي فرقة ينتمي قطري؟","options":["المعتزلة","الأزارقة من الخوارج","الشيعة","المرجئة"],"answer":1,"explanation":""},{"question":"متى قُتل قطري بحسب الشرح؟","options":["في الجاهلية","في عهد النبي","في ولاية الحجاج","في عهد عمر"],"answer":2,"explanation":""},{"question":"ما موضوع القطعة؟","options":["الغزل","الرثاء","الهجاء","الحث على الشجاعة والإقدام وثبات القلب"],"answer":3,"explanation":""},{"question":"ما معنى (الحمام)؟","options":["الموت","الطير","الحياة","الراحة"],"answer":0,"explanation":""},{"question":"ما معنى (يوم الوغى)؟","options":["يوم العيد","يوم الحرب","يوم السوق","يوم السفر"],"answer":1,"explanation":""},{"question":"بماذا شبه الشاعر نفسه في الحرب؟","options":["كأنه جبل","كأنه نهر","كأنه غرض تتعاوره الرماح","كأنه طير"],"answer":2,"explanation":""},{"question":"بماذا خُضب اللجام والسرج؟","options":["بالحناء","بالطين","بالماء","بدم الجروح"],"answer":3,"explanation":""},{"question":"ماذا يقصد بـ(جذع البصيرة قارح الإقدام)؟","options":["أن بصيرته قوية وإقدامه ازداد خبرة","أنه صغير السن","أنه جبان","أنه ركب فرسًا"],"answer":0,"explanation":""},{"question":"ما الذي لم يردّه عن خوض الحروب؟","options":["كبر السن","ما ذكره من الجراح والدماء","الخوف","الفقر"],"answer":1,"explanation":""}]}]},{"id":"alhamasa-12","title":"قطعة 12: ابن زيابة التيمي","summary":"","segments":[{"images":[{"src":"assets/hamasa/10-339-q12_verses-abb4036a.png","alt":"أبيات القطعة من الكتاب"}],"body":["اسمه سلمة بن ذهل، وقيل عمرو بن الحارث بن همام، من بني تيم الله بن ثعلبة، من بني بكر بن وائل، وزيابة اسم أمه، شاعر جاهلي. وقد اضطربت الأقوال في نسبته، ولعل عمرًا المذكور في القطعة هو عمرو بن لأي من بني تيم الله بن ثعلبة. وسبب القطعة أن عمرًا هدَّد قومَ الشاعر وأوعدهم، فقال الشاعر هذه القطعة يسخر من تهديده، ثم يتهكم به ويعرِّض بفروسيته ويصفه أنه ليس للتهديد بأهل، وأنه ليس من الفروسية والشجاعة في شيء، ثم يذكِّره بيوم كان للشاعر عليهم، فطعن فيه رجلًا منهم فأحدث على نفسه. وذكر المرزوقي أن الغالب على ظنه أن البيت الأخير لم يختره أبو تمام."],"vocab":[["نُبِّئت","أي أُخبرت؛ والنبأ الخبر، ويقال نبّأتُ وأنبأتُ"],["غارزًا رأسه في سِنة","الغرز الإدخال والتثبيت؛ والسِّنة أول النوم؛ وهو كناية عن الجهل والاغترار بالنفس وترك التحفظ"],["يوعد","يقال أوعد يوعد في الشر غالبًا كالتهديد، ووعد يعد في الخير غالبًا"],["أخواله","الذين منهم ابن زيابة"],["غير مأمونة","لا يؤمن فعلها ولا يوثق بها، يصفه متهكمًا بأنه يقول ما لا يفعل"],["كفّي","الكفّ راحة اليد مع الأصابع"],["اللِّبد","ما يوضع على ظهر الدابة من سرج أو قتب"],["تزواله","مصدر للتكثير من الزوال، يقال زال يزول إذا مال وانتقل"],["ثروة","المال الكثير"],["مستودَع","محفوظ عنده، من الاستيداع وهو الحفظ"],["آليتُ","أي حلفتُ وأقسمتُ، والإيلاء الحلف"],["فدخِّنوا","من الدخان، والمراد به هنا الطيب والبخور، يعيره برجل منهم طُعِن فأحدث"],["سربال","القميص أو الدرع، وقيل: كل ما لُبس فهو سربال، لأنه تسربل به"]],"meaning":[["1-2","لقد أخبروني أن عمرًا يهددنا ويتوعدنا! ألا إن هذا الغِرَّ جامحٌ في جهالاته، سادرٌ في غيِّه، وليس تهديده إلا كسائر أقاويله التي يُرغي بها ويُزبِد ولا يفعل منها شيئًا، فهو كثير الكلام قليل الفعال."],["3-5","أما أنا فإني إذا ركبتُ الخيل لا أملأ كفِّي من الرُّمح فيعجزني عن حمل باقي السلاح، بل أنا من أهل الطراد والطعن والرمي، ولستُ ممن يتبَع السرج أينما ذهب، فيميل مع ميلانه ولا يثبت على الخيل، ولستُ ممن يقتني السلاحَ للمال والتجارة، فإني كثير الحروب، محتاجٌ لدرعي أبغي بها بدلًا من مال، فإنما المال وديعة عند الناس. وإني قد حلفتُ بالله أن أتجنَّب قتالكم حتى يتطيَّب المقاتل منكم ويطيَّب ملابسه، لئلا يحدثَ كصاحبكم فيُنتِن علينا المكان."]]},{"questions":[{"question":"من قائل هذه القطعة؟","options":["ابن زيابة التيمي","الشميذر الحارثي","قطري بن الفجاءة","عمرو بن معد يكرب"],"answer":0,"explanation":""},{"question":"من هي زيابة؟","options":["زوجته","أمّ الشاعر","أخته","جدّته"],"answer":1,"explanation":""},{"question":"من أي القبائل الشاعر؟","options":["من تميم","من قيس","من بني تيم الله بن ثعلبة من بكر بن وائل","من طيئ"],"answer":2,"explanation":""},{"question":"ما سبب القطعة؟","options":["أن الشاعر قتل رجلًا","أن عمرًا مات","أن الشاعر ضيّع ماله","أن عمرًا هدّد قوم الشاعر وتوعدهم"],"answer":3,"explanation":""},{"question":"ما معنى (غارزًا رأسه في سِنة)؟","options":["كناية عن الجهل والاغترار بالنفس","أنه نائم حقًا","أنه مريض","أنه راكب"],"answer":0,"explanation":""},{"question":"كيف يصف الشاعر عمرًا؟","options":["قليل الكلام","كثير الكلام قليل الفعال","شجاعًا","كريمًا"],"answer":1,"explanation":""},{"question":"ما معنى (اللِّبد)؟","options":["السيف","الرمح","ما يوضع على ظهر الدابة","الخيمة"],"answer":2,"explanation":""},{"question":"لماذا يقتني الشاعر الدرع؟","options":["للتجارة","للزينة","للهدية","ليدافع بها في الحرب لا للتجارة"],"answer":3,"explanation":""},{"question":"ماذا تعني (آليتُ)؟","options":["حلفتُ وأقسمتُ","رجعتُ","نسيتُ","هربتُ"],"answer":0,"explanation":""},{"question":"ما المقصود بقوله (فدخِّنوا المرءَ وسربالَه)؟","options":["الدعوة إلى وليمة","التعريض برجل منهم طُعن فأحدث فيحتاج إلى الطيب","التهديد بحرق بيتهم","الدعاء بالخير"],"answer":1,"explanation":""},{"question":"بماذا وصف الشاعر عمرًا في فروسيته؟","options":["بالشجاعة","بالكرم","بالعجز عن حمل السلاح وعدم الثبات على الخيل","بالحلم"],"answer":2,"explanation":""}]}]},{"id":"alhamasa-13","title":"قطعة 13: الأشتر النخعي","summary":"","segments":[{"images":[{"src":"assets/hamasa/11-340-q13_verses-2a3e0f86.png","alt":"أبيات القطعة من الكتاب"}],"body":["هو مالك بن الحارث بن عبد يغوث المذحجي النخعي، من بني النَّخَع، واسم النخع جَسر بن عمرو من بني مالك بن أدد (مذحج). وسمي الأشتر لضربة أصابته يوم اليرموك فسالت جراحتُه قيحًا على عينه فشتَرَها، والشَّتر انشقاق جفن العين. كان سيدًا فارسًا شجاعًا وفصيحًا شهمًا مطاعًا، أدرك الجاهلية والإسلام، وله أخبار في مقتل عثمان ثم في أحداث الفتنة بعد ذلك، شهد الجمل وصفين وغيرها، وكان في صفّ علي. وفي هذه القطعة يصف شجاعته وإقدامه ويُقسم على ذلك، ويصف مشهد الحرب، وقد كان الأشتر ممن ظهرت شجاعته واتضح بأسه في تلك الفتنة بين علي ومعاوية."],"vocab":[["بقَّيتُ","أبقيتُ وادّخرتُ"],["وفري","الوَفر المال الكثير المدَّخر"],["انحرفتُ","الانحراف الميل والانعطاف"],["العُلا","المعالي ومكارم الأخلاق"],["عَبوس","الكلوح والانقباض؛ وهذه الأخبار السابقة صفات مذمومة للأضياف"],["أشُنّ","أصبّ وأفرّق الغارة، وأصل الشَّنّ الصب"],["ابن حرب","هو معاوية بن أبي سفيان رضي الله عنه"],["غارة","من الإغارة، وهي الهجوم والانقضاض"],["نهاب نفوس","النِّهاب ما يُنتهب ويُذهب به"],["السَّعالي","جمع سعلاة وهي ضرب من الجن، وهو هنا تشبيه للخيل بالجنّ في المضاء وسرعة النفوذ"],["شُزَّبًا","جمع شازب، يعني الخيل اليابسة من الضُّمر"],["بيض","أي برجال بيض، والعرب تجعل البياض كناية عن الكرم وطيب الفعال"],["الكريهة","الأمر المكروه، وأكثر استعمالها في الحرب"],["شوس","جمع أشوَس، وهو الذي ينظر بطرف عينه تكبُّرًا"],["حمي الحديد","أي سلاح المعركة، لطول الحرب واشتدادها"],["مضانُ برق","يقال مَضَّ البرقُ ومضانًا إذا لمع"],["شُعاع شموس","مبالغة في التشبيه على عادة العرب"]],"meaning":[["1-2","جعلني الله ممن يبخل بماله فلا ينفقه، وممن يتنكّب درب مكارم الأخلاق ويتجانف عن معالي الأمور فلا يأتيها، وممن يسيء إلى ضيفه فلا يحفظ حرمته، إن لم أهجم هجومًا شديدًا على جيش معاوية يذهب بنفوس ناسٍ وينتهب آجالهم."],["3-4","وسيكون هذا الهجوم بخيلٍ ضامرةٍ مثل الجن في سرعتها، وعليها رجال كرام أشراف، أعزَّة أشداء حين تشتد الحرب. فإذا اضطرمت نارُها وطالت مدتها، رأيت بريقَ السلاح كأنه من شدة احتمائه لمعانُ البروق أو شعاع الشموس!"]]},{"questions":[{"question":"من قائل هذه القطعة؟","options":["زفر بن الحارث","الأشتر النخعي","قطري بن الفجاءة","ابن زيابة"],"answer":1,"explanation":""},{"question":"إلى أي قبيلة ينتمي الأشتر؟","options":["بنو تميم","بنو كلاب","بنو النخع من مذحج","بنو بكر"],"answer":2,"explanation":""},{"question":"لماذا سمي الأشتر؟","options":["لأنه أعور","لشدة غضبه","لطول شعره","لضربة أصابته يوم اليرموك فشتَرت جفن عينه"],"answer":3,"explanation":""},{"question":"مع أي صف كان الأشتر في الفتنة؟","options":["مع علي رضي الله عنه","مع معاوية","مع الخوارج","لم يشهد شيئًا"],"answer":0,"explanation":""},{"question":"ما معنى (الوَفر)؟","options":["الخيل","المال الكثير المدَّخر","السلاح","الطعام"],"answer":1,"explanation":""},{"question":"ما معنى (عَبوس) في الشرح؟","options":["الكرم","الضحك","الكلوح والانقباض","السرعة"],"answer":2,"explanation":""},{"question":"ماذا يقصد الشاعر بـ(ابن حرب)؟","options":["أبا سفيان","علي بن أبي طالب","رجلًا من قومه","معاوية بن أبي سفيان"],"answer":3,"explanation":""},{"question":"ما الذي شبه به الشاعر خيله؟","options":["بالسعالي وهي ضرب من الجن","بالطير","بالريح","بالسيل"],"answer":0,"explanation":""},{"question":"ما معنى (شُزَّبًا)؟","options":["الخيل السمينة","الخيل اليابسة من الضُّمر","الخيل البيضاء","الخيل الصغيرة"],"answer":1,"explanation":""},{"question":"ماذا تكني العرب بالبياض في (ببيضٍ)؟","options":["الشيب","المرض","الكرم وطيب الفعال","الخوف"],"answer":2,"explanation":""},{"question":"بماذا شبه الشاعر لمعان السلاح؟","options":["بالنجوم","بالقمر","بالنار","بلمعان البروق أو شعاع الشموس"],"answer":3,"explanation":""},{"question":"ما الغرض من هذه القطعة؟","options":["وصف شجاعته وإقدامه والقسم على ذلك","الرثاء","الغزل","الاعتذار"],"answer":0,"explanation":""}]}]}]};
